id:"8.15",src:7,srcName:"2030 Agenda: Goal 11 – Sustainable cities and communities",h:1,hs:1,title:"2030 Agenda: Goal 11 – Sustainable Cities and Communities",book:"PASSION 3 น.115 · Ex.1–4",
ind:["ต 1.1 ม.3/4","ต 1.3 ม.3/3","ต 2.2 ม.3/2","ต 3.1 ม.3/1","ต 4.2 ม.3/2"],
